entries[92049] = { ["name"] = "Mercenary Contract: Mage", ["text"] = "Use: Hire a mage that casts Arcane Brilliance on nearby Horde players, free of charge.\n\nArcane Brilliance\n30 yd range\nInstant\nRequires Mage Infuses the target with brilliance, increasing their spell power by 10% and their critical strike chance by 5% for 1 hour. Only works in Krasarang Wilds." }
entries[92050] = { ["name"] = "Mercenary Contract: Paladin", ["text"] = "Use: Hire a paladin that casts Blessing of Might on nearby Horde players, free of charge.\n\nBlessing of Might Level 35 30 yd range\nInstant\nRequires Paladin Places a Blessing on the friendly target, increasing mastery by 59 . Only works in Krasarang Wilds." }
entries[92051] = { ["name"] = "Mercenary Contract: Priest", ["text"] = "Use: Hire a priest that casts Power Word: Fortitude on nearby Horde players, free of charge.\n\nPower Word: Fortitude 4.4% of base mana 40 yd range Instant\nRequires Priest Infuses the target with vitality, increasing Stamina by 10% for 1 hour. Only works in Krasarang Wilds." }
